INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3112647, 436817, 30049, '<td valign="top">Very thin DOF on this.  Would like to see more of it in focus and with better lighting (or adjust exposure in-camera).<br/> <br/>First challenge?  The text in the border is a no-no (no copyrights, etc...) - take a peek at the rules when you get a moment so you don''t run into this with your next entry.<br/> <br/>Good luck.</td>', 'Very thin DOF on this.  Would like to see more of it in focus and with better lighting (or adjust exposure in-camera). First challenge?  The text in the border is a no-no (no copyrights, etc...) - take a peek at the rules when you get a moment so you don''t run into this with your next entry. Good luck.', '2006-12-13 10:28:19.000000', NULL, 1),
(3112648, 438117, 56254, '<td valign="top">what is for sale here?</td>', 'what is for sale here?', '2006-12-13 10:28:38.000000', NULL, 1),
(3112655, 437964, 26001, '<td valign="top">I like the colors and crispness of subjects. although the photo feels a little crowded.</td>', 'I like the colors and crispness of subjects. although the photo feels a little crowded.', '2006-12-13 10:29:44.000000', NULL, 1),
(3112657, 437470, 30049, '<td valign="top">Wonderful job of selective desat.  Certainly made this vendor jump out as it would have been lost in the "busyness" otherwise.  Good job of PP (vignetting, blur, desat, etc...).  Nicely done.</td>', 'Wonderful job of selective desat.  Certainly made this vendor jump out as it would have been lost in the "busyness" otherwise.  Good job of PP (vignetting, blur, desat, etc...).  Nicely done.', '2006-12-13 10:30:01.000000', NULL, 1),
(3112661, 435489, 56254, '<td valign="top">looks like the on-camera flash was used here ...</td>', 'looks like the on-camera flash was used here ...', '2006-12-13 10:30:51.000000', NULL, 1),
(3112664, 437454, 26001, '<td valign="top">I generally dont mind lens distortion but i wish you had used it here to create some dramatic effect. very nice tonal range in the bw conversion though</td>', 'I generally dont mind lens distortion but i wish you had used it here to create some dramatic effect. very nice tonal range in the bw conversion though', '2006-12-13 10:31:14.000000', NULL, 1),
(3112667, 437649, 56254, '<td valign="top">fantastic!  This is what the challenge was all about ... you deserve to win blue with this shot ... good luck!!</td>', 'fantastic!  This is what the challenge was all about ... you deserve to win blue with this shot ... good luck!!', '2006-12-13 10:31:39.000000', NULL, 1),
(3112671, 437734, 29293, '<td valign="top">super colors</td>', 'super colors', '2006-12-13 10:32:09.000000', NULL, 1),
(3112672, 436536, 26001, '<td valign="top">hehehe...i like the expression on statue''s face :)</td>', 'hehehe...i like the expression on statue''s face :)', '2006-12-13 10:32:13.000000', NULL, 1),
(3112673, 437649, 52549, '<td valign="top">Cool shot, works well in b/w.</td>', 'Cool shot, works well in b/w.', '2006-12-13 10:32:39.000000', NULL, 1),
(3112674, 436492, 29293, '<td valign="top">great perspective</td>', 'great perspective', '2006-12-13 10:32:39.000000', NULL, 1),
(3112679, 437736, 52549, '<td valign="top">Good use of negative space here. Nice subject ;-)</td>', 'Good use of negative space here. Nice subject ;-)', '2006-12-13 10:33:28.000000', NULL, 1),
(3112682, 438009, 29293, '<td valign="top">i wish you would have moved around those plants so we could see better</td>', 'i wish you would have moved around those plants so we could see better', '2006-12-13 10:34:06.000000', NULL, 1),
(3112685, 438027, 29293, '<td valign="top">nice graphic</td>', 'nice graphic', '2006-12-13 10:34:25.000000', NULL, 1),
(3112688, 438023, 56057, '<td valign="top">The dodging done on the folks in the top right is a little messy. It would have been better to dodge JUST the people or add a stronger gradient around them making the dodging more subtle.</td>', 'The dodging done on the folks in the top right is a little messy. It would have been better to dodge JUST the people or add a stronger gradient around them making the dodging more subtle.', '2006-12-13 10:35:06.000000', NULL, 1),
(3112691, 437842, 52549, '<td valign="top">Good composition and colours but it looks kind of fuzzy.</td>', 'Good composition and colours but it looks kind of fuzzy.', '2006-12-13 10:36:21.000000', NULL, 1),
(3112692, 435538, 52549, '<td valign="top">Very good. the colours are wonderful.</td>', 'Very good. the colours are wonderful.', '2006-12-13 10:36:26.000000', NULL, 1),
(3112699, 437722, 52549, '<td valign="top">Nice shot, but it looks more like someones dining room rather than a sales place.</td>', 'Nice shot, but it looks more like someones dining room rather than a sales place.', '2006-12-13 10:38:51.000000', NULL, 1),
(3112737, 436494, 69537, '<td valign="top">Unique colors!</td>', 'Unique colors!', '2006-12-13 10:47:47.000000', NULL, 1),
(3112757, 437722, 57260, '<td valign="top">Looks like a Real Estate picture of a house for sale. I would work on the sharpening technique a bit. There is some halo-ing especially visible around the legs of the chairs at the left. It looks like the focus wasn''t quite sharp and then in post processing perhaps you tried to sharpen it too much or the radius was too high hence the halos. I would also crop out the (barstool?) to the far left - it distracts.</td>', 'Looks like a Real Estate picture of a house for sale. I would work on the sharpening technique a bit. There is some halo-ing especially visible around the legs of the chairs at the left. It looks like the focus wasn''t quite sharp and then in post processing perhaps you tried to sharpen it too much or the radius was too high hence the halos. I would also crop out the (barstool?) to the far left - it distracts.', '2006-12-13 10:53:44.000000', NULL, 1),
(3112785, 437778, 56057, '<td valign="top">The colors seem a little off, also the amount of noise makes the picture feel more cluttered than it is.</td>', 'The colors seem a little off, also the amount of noise makes the picture feel more cluttered than it is.', '2006-12-13 10:59:16.000000', NULL, 1),
(3112787, 437761, 56057, '<td valign="top">A little too warm.</td>', 'A little too warm.', '2006-12-13 10:59:38.000000', NULL, 1),
(3112802, 437620, 57260, '<td valign="top">You know what I would do to improve this composition is to use a wide angle lens and get down low with my face and camera practically flat on the fish to fill most of the frame with fish (the subject) and a medium aperture to blur the background just enough that the busy-ness doesn''t distract too much but not too much so one can still get a sense of the location.</td>', 'You know what I would do to improve this composition is to use a wide angle lens and get down low with my face and camera practically flat on the fish to fill most of the frame with fish (the subject) and a medium aperture to blur the background just enough that the busy-ness doesn''t distract too much but not too much so one can still get a sense of the location.', '2006-12-13 11:03:03.000000', NULL, 1),
(3112811, 436469, 57260, '<td valign="top">I like it. Nice leading lines.</td>', 'I like it. Nice leading lines.', '2006-12-13 11:05:29.000000', NULL, 1),
(3112827, 436817, 56057, '<td valign="top">I am not sure what the focus is.</td>', 'I am not sure what the focus is.', '2006-12-13 11:07:29.000000', NULL, 1),
(3112830, 438135, 56057, '<td valign="top">What is for sale? or was?</td>', 'What is for sale? or was?', '2006-12-13 11:07:54.000000', NULL, 1),
(3112831, 436258, 57260, '<td valign="top">Good composition. His face is perhaps a bit too dark. Seeing as it is an advanced editing challenge, I would add a vignette or burn in the background a bit just to highlight the subject a little.</td>', 'Good composition. His face is perhaps a bit too dark. Seeing as it is an advanced editing challenge, I would add a vignette or burn in the background a bit just to highlight the subject a little.', '2006-12-13 11:08:32.000000', NULL, 1),
(3112844, 438009, 57260, '<td valign="top">There''s a bit too much going on in the picture and the cars in the background is just way distracting. Try shooting from a different angle so you dont have such a busy background or use a wide open aperture to blur the background.</td>', 'There''s a bit too much going on in the picture and the cars in the background is just way distracting. Try shooting from a different angle so you dont have such a busy background or use a wide open aperture to blur the background.', '2006-12-13 11:11:53.000000', NULL, 1),
(3112854, 436309, 57260, '<td valign="top">Oh excellent. Made me chuckle and your title is spot on. The slanting road bugs me a bit and it''s a pity about the white sky, but it tells a good story.</td>', 'Oh excellent. Made me chuckle and your title is spot on. The slanting road bugs me a bit and it''s a pity about the white sky, but it tells a good story.', '2006-12-13 11:15:25.000000', NULL, 1),
(3112883, 437643, 67698, '<td valign="top">Santa! What happened? Are your elves on strike?<br/> <br/>Great shot. Very atmospheric.</td>', 'Santa! What happened? Are your elves on strike? Great shot. Very atmospheric.', '2006-12-13 11:22:59.000000', NULL, 1),
(3112890, 437234, 57260, '<td valign="top">The colors of the boat seems a bit too saturated to fit in with the old rusty feeling it portrays. Perhaps it converting it to B&amp;W or sepia will improve it. Also a straight horizon will work MUCH better.</td>', 'The colors of the boat seems a bit too saturated to fit in with the old rusty feeling it portrays. Perhaps it converting it to B&W or sepia will improve it. Also a straight horizon will work MUCH better.', '2006-12-13 11:24:40.000000', NULL, 1),
(3112892, 438038, 67698, '<td valign="top">Aah, leftovers from the Dirt contest, eh?<br/> <br/>Its a fun idea, and I like the composition. I''m not sure if the reflections off the aluminum foil in the background are a good thing, but otherwise I like it!</td>', 'Aah, leftovers from the Dirt contest, eh? Its a fun idea, and I like the composition. I''m not sure if the reflections off the aluminum foil in the background are a good thing, but otherwise I like it!', '2006-12-13 11:24:59.000000', NULL, 1),
(3112909, 438009, 67698, '<td valign="top">I don''t think the shot was composed in a good way. What is the subject of the photo? The plant in the center? The cows? The people in the background? Each one of the aforementioned candidates are ineffectively presented. I would have shifted the shot to the left, to concentrate on the people and the cows for sale in front of them, so that the tent leg didn''t get in the way. The way it is now, the shot doesn''t quite work for me.</td>', 'I don''t think the shot was composed in a good way. What is the subject of the photo? The plant in the center? The cows? The people in the background? Each one of the aforementioned candidates are ineffectively presented. I would have shifted the shot to the left, to concentrate on the people and the cows for sale in front of them, so that the tent leg didn''t get in the way. The way it is now, the shot doesn''t quite work for me.', '2006-12-13 11:28:53.000000', NULL, 1),
(3112923, 436494, 26001, '<td valign="top">Image processing (IR) looks good on the tree/branches, leaves, sky and background trees but main subjects (lady and lamb) get lost in the scene.</td>', 'Image processing (IR) looks good on the tree/branches, leaves, sky and background trees but main subjects (lady and lamb) get lost in the scene.', '2006-12-13 11:31:57.000000', NULL, 1),
(3112926, 436030, 67698, '<td valign="top">Its a good shot, and definitely fits the theme, but the shot feels underexposed and the tonal range has been cut severely. I wish there was more color in this shot!</td>', 'Its a good shot, and definitely fits the theme, but the shot feels underexposed and the tonal range has been cut severely. I wish there was more color in this shot!', '2006-12-13 11:32:16.000000', NULL, 1),
(3112927, 437655, 57260, '<td valign="top">I like it. The selective desat works really well here - it makes the subject jump out from the picture. I also like the admiring expression on the man''s face. Very good composition.</td>', 'I like it. The selective desat works really well here - it makes the subject jump out from the picture. I also like the admiring expression on the man''s face. Very good composition.', '2006-12-13 11:32:24.000000', NULL, 1),
(3112932, 437741, 67698, '<td valign="top">Ha! I''ll take two! Great idea, and ver well executed. Love the exotic-looking jars and soul-stealing paraphernalia. Great background too. Well done!</td>', 'Ha! I''ll take two! Great idea, and ver well executed. Love the exotic-looking jars and soul-stealing paraphernalia. Great background too. Well done!', '2006-12-13 11:33:39.000000', NULL, 1),
(3112954, 436492, 57260, '<td valign="top">This is a really busy picture and in this instance it works really well since it supports the theme of the picture. I like it.</td>', 'This is a really busy picture and in this instance it works really well since it supports the theme of the picture. I like it.', '2006-12-13 11:37:06.000000', NULL, 1),
(3112963, 436502, 57260, '<td valign="top">Shame on Santa!</td>', 'Shame on Santa!', '2006-12-13 11:38:35.000000', NULL, 1),
