(3117092, 436298, 58610, '<td valign="top">I think you could have cropped out the two on the right and concentrated just on the lamp and the one head. I like the lighting a lot, and the black background works well.</td>', 'I think you could have cropped out the two on the right and concentrated just on the lamp and the one head. I like the lighting a lot, and the black background works well.', '2006-12-14 11:47:57.000000', NULL, 1),
(3117096, 437624, 48982, '<td valign="top">Nice formal image.  I''d like to see it in different light since there''s such an absence of color.</td>', 'Nice formal image.  I''d like to see it in different light since there''s such an absence of color.', '2006-12-14 11:49:05.000000', NULL, 1),
(3117097, 437285, 56502, '<td valign="top">I''d think either more or even less of the head would be better. Like that it looks cut off by accident, not intentionally.</td>', 'I''d think either more or even less of the head would be better. Like that it looks cut off by accident, not intentionally.', '2006-12-14 11:49:10.000000', NULL, 1),
