(3117889, 436309, 68059, '<td valign="top">The idea is great, photo appears slightly tilted and the sky could be better.</td>', 'The idea is great, photo appears slightly tilted and the sky could be better.', '2006-12-14 16:49:01.000000', NULL, 1),
(3117895, 437799, 68059, '<td valign="top">I don''t know, the name strikes me as a slightly cruel comment.  The tone of the photo appears dull with disturbing highlights popping up here and there.  Sorry, doesn''t make it for me.</td>', 'I don''t know, the name strikes me as a slightly cruel comment.  The tone of the photo appears dull with disturbing highlights popping up here and there.  Sorry, doesn''t make it for me.', '2006-12-14 16:50:50.000000', NULL, 1),
(3117896, 436494, 68059, '<td valign="top">Is the lady selling the lamb?  For some odd reason though I like this photo, the original colors are refreshing.</td>', 'Is the lady selling the lamb?  For some odd reason though I like this photo, the original colors are refreshing.', '2006-12-14 16:51:58.000000', NULL, 1),
(3117901, 437853, 68059, '<td valign="top">Nope, on so many levels this photo is just not cutting it.</td>', 'Nope, on so many levels this photo is just not cutting it.', '2006-12-14 16:53:02.000000', NULL, 1),
(3117905, 435972, 68059, '<td valign="top">Haphazard use of colors - just don''t quite get it.  It would have been more direct if you''d stuck to the lady in blue, and her honey :)  Also a lot of disturbing artifacts/cars/trees etc.  This photo would benefit from the old advice:  If you want a better picture, get nearer to the subject.</td>', 'Haphazard use of colors - just don''t quite get it.  It would have been more direct if you''d stuck to the lady in blue, and her honey :)  Also a lot of disturbing artifacts/cars/trees etc.  This photo would benefit from the old advice:  If you want a better picture, get nearer to the subject.', '2006-12-14 16:56:09.000000', NULL, 1),
