(3119996, 437800, 69968, '<td valign="top">i do like the photo very imaginative.</td>', 'i do like the photo very imaginative.', '2006-12-15 07:48:49.000000', NULL, 1),
(3120112, 435845, 24073, '<td valign="top">Love the idea, and though the content is dramatic enough I would of liked to see a more dramatic lighting set-up.  Still awesome, and gutsy.  I''m going to be interested in seeing how this one does, I''ll be watching.<br/> <br/>How do you like the title "Souls for Sale".  Again a title like that would of probably damaged your avg.  The way you have it is probably smarter, because you can''t tell one way or another what the message is.  GL.</td>', 'Love the idea, and though the content is dramatic enough I would of liked to see a more dramatic lighting set-up.  Still awesome, and gutsy.  I''m going to be interested in seeing how this one does, I''ll be watching. How do you like the title "Souls for Sale".  Again a title like that would of probably damaged your avg.  The way you have it is probably smarter, because you can''t tell one way or another what the message is.  GL.', '2006-12-15 09:02:56.000000', NULL, 1),
(3120121, 436494, 24073, '<td valign="top">A beautiful photo that I think is going to go through hardknocks for DNMC.  I like it, but find myself having to build a scenario for this to meet "for sale".  I guess she is selling lambs. GL.</td>', 'A beautiful photo that I think is going to go through hardknocks for DNMC.  I like it, but find myself having to build a scenario for this to meet "for sale".  I guess she is selling lambs. GL.', '2006-12-15 09:06:25.000000', NULL, 1),
