(3123439, 436880, 69246, '<td valign="top">A bit dark</td>', 'A bit dark', '2006-12-16 11:51:38.000000', NULL, 1),
(3123710, 437470, 67585, '<td valign="top">Nice use of selective color, I like how you were able to "blend" it into the black and white</td>', 'Nice use of selective color, I like how you were able to "blend" it into the black and white', '2006-12-16 15:02:44.000000', NULL, 1),
(3123719, 438033, 67585, '<td valign="top">Nice photo, I think this would work really well as a black and white.</td>', 'Nice photo, I think this would work really well as a black and white.', '2006-12-16 15:07:11.000000', NULL, 1),
(3123729, 437301, 67585, '<td valign="top">Nice photo, its a little too yellowish IMO, maybe a white balance issue / color correction in PS would do the trick.</td>', 'Nice photo, its a little too yellowish IMO, maybe a white balance issue / color correction in PS would do the trick.', '2006-12-16 15:15:40.000000', NULL, 1),
(3123848, 435951, 26756, '<td valign="top">Swarthy</td>', 'Swarthy', '2006-12-16 16:48:18.000000', NULL, 1),
(3123905, 437470, 32968, '<td valign="top">Sense Appeal-10<br/>Layout-10<br/>Creativity-10<br/>Applied Techniques-10<br/>Meets the Challenge-10<br/> <br/>Average-10 - It''s all there. Very cool piece of work :)</td>', 'Sense Appeal-10Layout-10Creativity-10Applied Techniques-10Meets the Challenge-10 Average-10 - It''s all there. Very cool piece of work :)', '2006-12-16 17:19:48.000000', NULL, 1),
(3123943, 436030, 32968, '<td valign="top">Sense Appeal-10<br/>Layout-10<br/>Creativity-8<br/>Applied Techniques-7<br/>Meets the Challenge-10<br/> <br/>Average-9 - I like the expression and the connection the subject is making with the camera. Great colors and definition. Don''t like the darkening at the bottom of the shot, but the halo effect around him is very nicely done. The structure on the right side of the photo is a bit distracting as well. Would make a great ad for "kindness and sharing" :) That''s the emotion I get from it.</td>', 'Sense Appeal-10Layout-10Creativity-8Applied Techniques-7Meets the Challenge-10 Average-9 - I like the expression and the connection the subject is making with the camera. Great colors and definition. Don''t like the darkening at the bottom of the shot, but the halo effect around him is very nicely done. The structure on the right side of the photo is a bit distracting as well. Would make a great ad for "kindness and sharing" :) That''s the emotion I get from it.', '2006-12-16 17:34:32.000000', NULL, 1),
(3123951, 437655, 32968, '<td valign="top">Huge Dodge fan has nothing else to say but "10" :)</td>', 'Huge Dodge fan has nothing else to say but "10" :)', '2006-12-16 17:37:25.000000', NULL, 1),
(3123977, 437729, 32968, '<td valign="top">As a mother, I despise this photo. PS3 my foot. Got enuf of them in my house! However, this is a nice shot for an ad. It is a bit hot in the white areas tho, detracting from the best view of the consoles features. More definition between the console, the paddle and the background would help. Only $399.99 you say? :P I gave it a 7</td>', 'As a mother, I despise this photo. PS3 my foot. Got enuf of them in my house! However, this is a nice shot for an ad. It is a bit hot in the white areas tho, detracting from the best view of the consoles features. More definition between the console, the paddle and the background would help. Only $399.99 you say? :P I gave it a 7', '2006-12-16 17:43:29.000000', NULL, 1),
(3123982, 436492, 32968, '<td valign="top">Love the humor in this :) Overwhelming to say the least - 8</td>', 'Love the humor in this :) Overwhelming to say the least - 8', '2006-12-16 17:45:18.000000', NULL, 1),
(3124262, 437853, 22478, '<td valign="top">Subject appears to be out of focus.</td>', 'Subject appears to be out of focus.', '2006-12-16 20:26:55.000000', NULL, 1),
(3124270, 437722, 22478, '<td valign="top">Doesn''t seem to conform to contest details, despite the caption.</td>', 'Doesn''t seem to conform to contest details, despite the caption.', '2006-12-16 20:32:04.000000', NULL, 1),
(3124282, 436492, 55838, '<td valign="top">This is just crazy!  How would anyone ever decide or even find what they are looking for in this store!?  I love the scale and perspective - so glad that lady is included.  Back to bump you up to 8.</td>', 'This is just crazy!  How would anyone ever decide or even find what they are looking for in this store!?  I love the scale and perspective - so glad that lady is included.  Back to bump you up to 8.', '2006-12-16 20:40:06.000000', NULL, 1),
