(3127589, 437174, 33552, '<td valign="top">Is it falling over or am I? Neat shot with lots of motion, both implied and explicit. Try reducing the reds in the shadows with levels or curves.</td>', 'Is it falling over or am I? Neat shot with lots of motion, both implied and explicit. Try reducing the reds in the shadows with levels or curves.', '2006-12-18 04:38:43.000000', NULL, 1),
(3127596, 437749, 33552, '<td valign="top">Nice shot, and nicely processed. I like the vignette here.</td>', 'Nice shot, and nicely processed. I like the vignette here.', '2006-12-18 04:40:19.000000', NULL, 1),
(3127609, 438021, 33552, '<td valign="top">I''ve seen a few of these and they make me cross-eyed. My eyes are pulled into the BG by the overall composition and simultaneously to the foreground by the focus. I wonder if a slightly wider DoF would help, or maybe focusing slightly farther into the frame.</td>', 'I''ve seen a few of these and they make me cross-eyed. My eyes are pulled into the BG by the overall composition and simultaneously to the foreground by the focus. I wonder if a slightly wider DoF would help, or maybe focusing slightly farther into the frame.', '2006-12-18 04:43:38.000000', NULL, 1),
(3127617, 437719, 33552, '<td valign="top">Nice scene, but what is the subject? The mountains, sky, road, building and car are all competing for attention. I get that the building is meant to be the main subject but it''s visually confusing.</td>', 'Nice scene, but what is the subject? The mountains, sky, road, building and car are all competing for attention. I get that the building is meant to be the main subject but it''s visually confusing.', '2006-12-18 04:46:05.000000', NULL, 1),
(3127620, 436733, 33552, '<td valign="top">Nice pattern and symmetry. I''d crop a bit off of the top. The bits of BG creeping in at the corners don''t add anything.</td>', 'Nice pattern and symmetry. I''d crop a bit off of the top. The bits of BG creeping in at the corners don''t add anything.', '2006-12-18 04:47:52.000000', NULL, 1),
(3127629, 437988, 33552, '<td valign="top">Unlike the similar shots I''ve rated so far, this one is less disorienting. Good job!!! (It''s the wider DoF.)</td>', 'Unlike the similar shots I''ve rated so far, this one is less disorienting. Good job!!! (It''s the wider DoF.)', '2006-12-18 04:49:27.000000', NULL, 1),
