INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3136627, 437643, 48890, '<td valign="top">This is a nice shot, although I think that it could be beneficial to wait for a better moment, for the craftsman to look down at his work, or even cast a glance into the lens, instead of looking at someone/something left out of the frame.<br/> <br/>The heavy black and white frame really makes it a pain to look at this image for longer than a few seconds.</td>', 'This is a nice shot, although I think that it could be beneficial to wait for a better moment, for the craftsman to look down at his work, or even cast a glance into the lens, instead of looking at someone/something left out of the frame. The heavy black and white frame really makes it a pain to look at this image for longer than a few seconds.', '2006-12-20 17:07:11.000000', NULL, 0),
(3136628, 437470, 4517, '<td valign="top">Nice one Beau :)</td>', 'Nice one Beau :)', '2006-12-20 17:07:16.000000', NULL, 0),
(3136637, 436492, 48890, '<td valign="top">I don''t like this image.  It is too up-front, and there is no accent, nothing to rest the eye upon.</td>', 'I don''t like this image.  It is too up-front, and there is no accent, nothing to rest the eye upon.', '2006-12-20 17:08:57.000000', NULL, 0),
(3136655, 437906, 48890, '<td valign="top">It would be nice to have something breaking the symmetry.  The kid in the lower right corner could be it, but his figure is not prominent enough.</td>', 'It would be nice to have something breaking the symmetry.  The kid in the lower right corner could be it, but his figure is not prominent enough.', '2006-12-20 17:12:12.000000', NULL, 0),
(3136806, 436742, 66384, '<td valign="top">I don''t have much to add to the comments below. I like this a lot, especially his concentration and the lighting. I agree that the red in his face (especially his ear) is over saturated. I gave this an 8 during voting. It''s a good photo for your portfolio, where the rules don''t apply, because the black background is very effective.</td>', 'I don''t have much to add to the comments below. I like this a lot, especially his concentration and the lighting. I agree that the red in his face (especially his ear) is over saturated. I gave this an 8 during voting. It''s a good photo for your portfolio, where the rules don''t apply, because the black background is very effective.', '2006-12-20 17:37:21.000000', NULL, 0),
(3136855, 436895, 66384, '<td valign="top">I''m afraid I helped to spoil your score. I gave this a 5. The reason was that it seemed cluttered. I think I would have liked it better if it was not just a photo of a sign and decorations, but somewhere I could actually go for the product (Christmas cheer). In other words, I''d like to see what could be done by including the door in the shot.</td>', 'I''m afraid I helped to spoil your score. I gave this a 5. The reason was that it seemed cluttered. I think I would have liked it better if it was not just a photo of a sign and decorations, but somewhere I could actually go for the product (Christmas cheer). In other words, I''d like to see what could be done by including the door in the shot.', '2006-12-20 17:50:13.000000', NULL, 0),
(3136876, 437778, 66384, '<td valign="top">I only gave this a 5 because the focus bothers me. Not only the OOF people, but the items on the table are hard to make out. What I do like about it is the little boy looking longingly at something on the table.</td>', 'I only gave this a 5 because the focus bothers me. Not only the OOF people, but the items on the table are hard to make out. What I do like about it is the little boy looking longingly at something on the table.', '2006-12-20 17:57:13.000000', NULL, 0),
(3136901, 437724, 66384, '<td valign="top">This is sadly very funny. I hate to say I''m afraid you are correct in your assessment. There''s not much I can say about the photo except it is lovely.</td>', 'This is sadly very funny. I hate to say I''m afraid you are correct in your assessment. There''s not much I can say about the photo except it is lovely.', '2006-12-20 18:05:47.000000', NULL, 0),
(3136956, 437739, 5585, '<td valign="top">WTG Milos...ribbon time...</td>', 'WTG Milos...ribbon time...', '2006-12-20 18:40:13.000000', NULL, 0),
(3137066, 437905, 45475, '<td valign="top">Awesome Hannes. I''m completely surprised this didn''t ribbon, it was one of my top picks. Absolutely stupendous black and white piece, congratulations on the top 10 finish!</td>', 'Awesome Hannes. I''m completely surprised this didn''t ribbon, it was one of my top picks. Absolutely stupendous black and white piece, congratulations on the top 10 finish!', '2006-12-20 19:10:39.000000', NULL, 0),
(3137071, 436880, 31399, '<td valign="top">I didn''t vote this challenge but I remember seeing this shot in thumbnails and opening it...I LAUGHED very loudly.  I love the spontaneous nature of the shot and thought it wasn''t just a run-of-the mill studio shot.  great capture and great shot from my view...no way would I have given this less than a 5</td>', 'I didn''t vote this challenge but I remember seeing this shot in thumbnails and opening it...I LAUGHED very loudly.  I love the spontaneous nature of the shot and thought it wasn''t just a run-of-the mill studio shot.  great capture and great shot from my view...no way would I have given this less than a 5', '2006-12-20 19:11:17.000000', NULL, 0),
(3137095, 438052, 31399, '<td valign="top">well...Aimee''s neighbors all know they''re nuts...but lawd whole town has to wonder ''what in the world is that gal up to???" lol nice idea and setup...nothing like purchasing a cowboy...yeeeehawww :-) love the shot....</td>', 'well...Aimee''s neighbors all know they''re nuts...but lawd whole town has to wonder ''what in the world is that gal up to???" lol nice idea and setup...nothing like purchasing a cowboy...yeeeehawww :-) love the shot....', '2006-12-20 19:22:02.000000', NULL, 0),
(3137147, 437767, 55838, '<td valign="top">I like the light &amp; shadow in this shot.  Nice subject matter too.</td>', 'I like the light & shadow in this shot.  Nice subject matter too.', '2006-12-20 19:45:09.000000', NULL, 0),
(3137155, 438038, 55838, '<td valign="top">Ha!  I thought this was such a cute shot and idea.  I''m laughing out loud at Jude''s comment - never thought of it as pulled pork before but ya know...?  : )</td>', 'Ha!  I thought this was such a cute shot and idea.  I''m laughing out loud at Jude''s comment - never thought of it as pulled pork before but ya know...?  : )', '2006-12-20 19:47:03.000000', NULL, 0),
